// The widths of the characters of every font a text style may have, for a text of height 1 and
// width factor 1. The numbers are data: do not edit them by hand.

/** One font, for a text of height 1 and width factor 1. */
export interface FontMetrics {
  /** How far below the baseline the bottom of a text is. */
  readonly below: number;
  /** How far each character of `FONT_METRICS_RANGES` moves the next one along. */
  readonly advances: readonly number[];
  /**
   * What the last character of a text adds to its length beyond the advances before it, less
   * its own advance.
   */
  readonly tails: readonly number[];
  /** Where the first character of a text starts to draw, from the text's first point. */
  readonly heads: readonly number[];
}

/** The first and last character of each run the tables hold, in order. */
export const FONT_METRICS_RANGES: readonly (readonly [number, number])[] = [
  [0x20, 0x7e],
  [0xa0, 0xff],
];

